    (excluded by last match), or False (re-included by last match). via_dir is
    True iff the last matching pattern matched an ancestor directory (meaning
    the file is excluded because its containing directory was excluded).
    """
    candidates = []
    for k in range(1, len(parts) + 1):
        candidates.append(("/".join(parts[:k]), k < len(parts)))
    status = None
    via_dir = False
    for negated, dir_only, regex in patterns:
        matched_as_dir = False
        matched_as_file = False
        for path, is_dir in candidates:
            if dir_only and not is_dir:
                continue
