#!/usr/bin/env python3
"""Fuzz: generate random trees + packignores and compare to packignore."""
import os
import random
import shutil
import string
import subprocess
import sys

sys.path.insert(0, "/work/repo")
from snapshot.ignore import ignored_files

TOOL = "/work/repo/tools/packignore"
BASE = "/tmp/pitests/fuzz"


def rand_name(r, chars=string.ascii_letters + string.digits + "._-"):
    # Pick small basenames so collisions and overlap happen often.
    return "".join(r.choice(chars) for _ in range(r.randint(1, 5)))


def rand_pattern(r):
    """Generate a random pattern."""
    specials = ["*", "?", "**"]
    parts = []
    depth = r.randint(1, 3)
    for i in range(depth):
        seg_chars = []
        for _ in range(r.randint(1, 4)):
            if r.random() < 0.3:
                seg_chars.append(r.choice(specials))
            else:
                seg_chars.append(r.choice(string.ascii_letters + "._"))
        parts.append("".join(seg_chars))
    p = "/".join(parts)
    if r.random() < 0.3:
        p = "/" + p
    if r.random() < 0.3:
        p = p + "/"
    if r.random() < 0.3:
        p = "!" + p
    return p


def rand_packignore(r):
    """Make .packignore content."""
    lines = []
    for _ in range(r.randint(0, 6)):
        choice = r.random()
        if choice < 0.1:
            lines.append(";" + rand_name(r))
        elif choice < 0.15:
            lines.append("")
        elif choice < 0.2:
            lines.append("  " * r.randint(0, 2))
        else:
            lines.append(rand_pattern(r))
    return "\n".join(lines) + "\n"


def rand_tree(r, root, depth=0, max_depth=3):
    """Make files/dirs under root."""
    n_files = r.randint(0, 4)
    n_dirs = r.randint(0, 2) if depth < max_depth else 0
    for _ in range(n_files):
        name = rand_name(r)
        path = os.path.join(root, name)
        if not os.path.exists(path):
            open(path, "w").close()
    for _ in range(n_dirs):
        name = rand_name(r)
        path = os.path.join(root, name)
        if not os.path.isfile(path):
            os.makedirs(path, exist_ok=True)
            rand_tree(r, path, depth + 1, max_depth)
    # Maybe add nested .packignore
    if depth > 0 and r.random() < 0.4:
        with open(os.path.join(root, ".packignore"), "w") as f:
            f.write(rand_packignore(r))


def canon(seq):
    return sorted(l for l in seq if l)


def run_case(seed):
    r = random.Random(seed)
    d = os.path.join(BASE, f"case_{seed}")
    if os.path.exists(d):
        shutil.rmtree(d)
    os.makedirs(d)
    with open(os.path.join(d, ".packignore"), "w") as f:
        f.write(rand_packignore(r))
    rand_tree(r, d, 0, max_depth=3)
    truth = subprocess.run([TOOL, d], capture_output=True, text=True)
    tout = canon(truth.stdout.splitlines())
    mine = canon(ignored_files(d))
    if tout == mine:
        return True, d, tout, mine
    return False, d, tout, mine


def main():
    N = int(sys.argv[1]) if len(sys.argv) > 1 else 300
    if os.path.exists(BASE):
        shutil.rmtree(BASE)
    os.makedirs(BASE)
    fails = []
    for seed in range(N):
        ok, d, t, m = run_case(seed)
        if not ok:
            fails.append((seed, d, t, m))
            if len(fails) <= 5:
                print(f"FAIL seed={seed} dir={d}")
                print(f"  truth: {t}")
                print(f"  mine:  {m}")
                with open(os.path.join(d, ".packignore")) as f:
                    print(f"  root packignore: {f.read()!r}")
    print(f"\n{N - len(fails)}/{N} pass")


if __name__ == "__main__":
    main()

